import { Controller } from '@nestjs/common';

// FN-SFR-042-03 재발급 수수료 등록은 화면만 만든다.
// POST /fee-records (createFeeRecord)는 먼저 하는 작업(TASK-169 등)에서 한 번만 만든다.
@Controller('api/v1')
export class FnSfr04203Controller {}

